def check_solution(edges, num_vertices=12):
    degrees = {i: 0 for i in range(num_vertices)}
    for i in range(0, len(edges), 2):
        u, v = edges[i], edges[i+1]
        degrees[u] += 1
        degrees[v] += 1

    for v, d in degrees.items():
        if not (1 <= d <= 3):
            return False, f"Vertex {v} has degree {d}"
    return True, "Valid"

edges = [0, 1, 2, 9, 2, 10, 2, 11, 3, 4, 5, 6, 7, 8]
print(check_solution(edges))
